import{_ as e,o as t,c as r,a5 as l}from"./chunks/framework.a5no_H3L.js";const f=JSON.parse('{"title":"MySQL 概览","description":"MySQL 是由 Oracle 维护的开源关系型数据库，默认存储引擎是 InnoDB。本页给出理解 MySQL 的整体地图：它由哪些部件决定行为、背后有哪些设计取向、什么场景适合继续用它。读完本页，从整体架构开始按主线深入。","frontmatter":{},"headers":[],"relativePath":"mysql/01-basics/chapter-01-overview.md","filePath":"mysql/01-basics/chapter-01-overview.md"}'),i={name:"mysql/01-basics/chapter-01-overview.md"};function s(c,a,d,o,n,h){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="mysql-概览" tabindex="-1" data-src-line="1" data-src-file="mysql/01-basics/chapter-01-overview.md">MySQL 概览 <a class="header-anchor" href="#mysql-概览" aria-label="Permalink to &quot;MySQL 概览&quot;">​</a></h1><p data-src-line="3" data-src-file="mysql/01-basics/chapter-01-overview.md">MySQL 是由 Oracle 维护的开源关系型数据库，默认存储引擎是 InnoDB。本页给出理解 MySQL 的整体地图：它由哪些部件决定行为、背后有哪些设计取向、什么场景适合继续用它。读完本页，从<a href="./chapter-02-architecture.html">整体架构</a>开始按主线深入。</p><p data-src-line="5" data-src-file="mysql/01-basics/chapter-01-overview.md">本专项面向已经掌握基础 SQL 的后端开发者，讨论 MySQL 在生产环境中的内部行为：一条 SQL 如何执行、数据如何落盘、并发如何隔离、性能由什么决定。不覆盖 SQL 语法入门，也不覆盖备份恢复等操作手册（操作见<a href="./../08-operations/chapter-01-backup-restore.html">运维管理</a>）。</p><h2 id="核心组成" tabindex="-1" data-src-line="7" data-src-file="mysql/01-basics/chapter-01-overview.md">核心组成 <a class="header-anchor" href="#核心组成" aria-label="Permalink to &quot;核心组成&quot;">​</a></h2><table tabindex="0"><thead data-src-line="9" data-src-file="mysql/01-basics/chapter-01-overview.md"><tr data-src-line="9" data-src-file="mysql/01-basics/chapter-01-overview.md"><th style="text-align:left;">组成</th><th style="text-align:left;">解决的问题</th><th style="text-align:left;">继续阅读</th></tr></thead><tbody data-src-line="11" data-src-file="mysql/01-basics/chapter-01-overview.md"><tr data-src-line="11" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">连接层与服务层</td><td style="text-align:left;">接收请求、解析 SQL、生成执行计划</td><td style="text-align:left;"><a href="./chapter-02-architecture.html">整体架构</a></td></tr><tr data-src-line="12" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">InnoDB 存储引擎</td><td style="text-align:left;">组织数据页、缓存、崩溃恢复和并发事务</td><td style="text-align:left;"><a href="./../02-storage-and-logging/chapter-01-data-page.html">存储与日志</a></td></tr><tr data-src-line="13" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">索引与优化器</td><td style="text-align:left;">缩小候选行范围并选择代价较低的执行方式</td><td style="text-align:left;"><a href="./../03-index/chapter-01-btree-index.html">B+ 树索引</a></td></tr><tr data-src-line="14" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">事务、MVCC 与锁</td><td style="text-align:left;">保证并发事务的隔离，并协调读写冲突</td><td style="text-align:left;"><a href="./../05-transaction-lock/chapter-01-overview.html">事务与锁</a></td></tr><tr data-src-line="15" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">SQL 与 Schema 特性</td><td style="text-align:left;">定义字符集、排序规则，使用窗口函数等能力</td><td style="text-align:left;"><a href="./../06-sql-and-schema/chapter-01-charset-collation.html">字符集与排序规则</a></td></tr><tr data-src-line="16" data-src-file="mysql/01-basics/chapter-01-overview.md"><td style="text-align:left;">复制与日志</td><td style="text-align:left;">同步变更、恢复数据并支持故障切换</td><td style="text-align:left;"><a href="./../07-replication-and-architecture/chapter-01-binlog-replication.html">复制与扩展架构</a></td></tr></tbody></table><p data-src-line="18" data-src-file="mysql/01-basics/chapter-01-overview.md">InnoDB 是 MySQL 的默认存储引擎，也是本专项的主要讨论对象。它通过 Buffer Pool 降低磁盘访问，通过 Redo Log 保证崩溃恢复，通过 Undo Log 和 Read View 支持 MVCC，通过索引与锁协调并发读写。</p><h2 id="四条设计主线" tabindex="-1" data-src-line="20" data-src-file="mysql/01-basics/chapter-01-overview.md">四条设计主线 <a class="header-anchor" href="#四条设计主线" aria-label="Permalink to &quot;四条设计主线&quot;">​</a></h2><p data-src-line="22" data-src-file="mysql/01-basics/chapter-01-overview.md">理解 MySQL 的行为，先抓住四条设计取向。后续所有章节都在展开它们，遇到具体问题时也能回到这四条线索定位原因。</p><ol data-src-line="24" data-src-file="mysql/01-basics/chapter-01-overview.md"><li data-src-line="24" data-src-file="mysql/01-basics/chapter-01-overview.md"><strong>日志先行</strong>。写请求先顺序写入 Redo Log，数据页再异步刷盘。顺序写远快于随机写，已提交的事务在崩溃后也能恢复。见 <a href="./../02-storage-and-logging/chapter-04-redo-log.html">Redo Log</a>。</li><li data-src-line="25" data-src-file="mysql/01-basics/chapter-01-overview.md"><strong>内存换磁盘 IO</strong>。Buffer Pool 缓存数据页：读先查内存，写先改内存中的页，脏页再异步刷回磁盘。热点数据留在内存里的比例越高，磁盘压力越小。见 <a href="./../02-storage-and-logging/chapter-02-buffer-pool.html">Buffer Pool</a>。</li><li data-src-line="26" data-src-file="mysql/01-basics/chapter-01-overview.md"><strong>数据按主键组织</strong>。InnoDB 使用聚簇索引，行数据存放在主键 B+ 树的叶子节点里，二级索引的叶子节点存主键值。主键的长度和取值方式直接影响二级索引的大小和写入是否产生页分裂。见 <a href="./../03-index/chapter-01-btree-index.html">B+ 树索引</a>。</li><li data-src-line="27" data-src-file="mysql/01-basics/chapter-01-overview.md"><strong>复制优先的扩展</strong>。读能力不足时先靠主从复制和读写分离分担，单机容量或写入吞吐到上限后再评估分库分表，而不是先拆库。见<a href="./../07-replication-and-architecture/chapter-01-binlog-replication.html">复制与扩展架构</a>。</li></ol><h2 id="适用与不适用" tabindex="-1" data-src-line="29" data-src-file="mysql/01-basics/chapter-01-overview.md">适用与不适用 <a class="header-anchor" href="#适用与不适用" aria-label="Permalink to &quot;适用与不适用&quot;">​</a></h2><p data-src-line="31" data-src-file="mysql/01-basics/chapter-01-overview.md">MySQL 适合以在线事务处理为主、读写并发较高、能通过主从复制扩展读能力的业务：请求以点查、范围查和短事务为主，数据量在单机容量内可控。</p><p data-src-line="33" data-src-file="mysql/01-basics/chapter-01-overview.md">遇到以下情况，应先重新评估数据模型、数据库产品和架构，而不是只加参数：</p><ul data-src-line="35" data-src-file="mysql/01-basics/chapter-01-overview.md"><li data-src-line="35" data-src-file="mysql/01-basics/chapter-01-overview.md">查询以复杂分析、大范围聚合为主，在线事务只占小头；</li><li data-src-line="36" data-src-file="mysql/01-basics/chapter-01-overview.md">需要跨地域的强一致多写，而主从复制的写入路径无法满足；</li><li data-src-line="37" data-src-file="mysql/01-basics/chapter-01-overview.md">单机容量或写入吞吐到达上限，且压缩、归档、分区已无法缓解。</li></ul><p data-src-line="39" data-src-file="mysql/01-basics/chapter-01-overview.md">选版本、比较 MariaDB，或决定使用云 RDS 还是自建时，见<a href="./../10-practice/chapter-01-version-and-selection.html">版本、产品与部署选型</a>。</p><h2 id="继续阅读" tabindex="-1" data-src-line="41" data-src-file="mysql/01-basics/chapter-01-overview.md">继续阅读 <a class="header-anchor" href="#继续阅读" aria-label="Permalink to &quot;继续阅读&quot;">​</a></h2><ul data-src-line="43" data-src-file="mysql/01-basics/chapter-01-overview.md"><li data-src-line="43" data-src-file="mysql/01-basics/chapter-01-overview.md">想知道一条 SQL 如何执行：阅读<a href="./chapter-02-architecture.html">整体架构</a>。</li><li data-src-line="44" data-src-file="mysql/01-basics/chapter-01-overview.md">想知道数据如何落盘、崩溃后如何恢复：阅读<a href="./../02-storage-and-logging/chapter-01-data-page.html">数据页与行格式</a>。</li><li data-src-line="45" data-src-file="mysql/01-basics/chapter-01-overview.md">查询变慢、需要判断执行方式：阅读<a href="./../04-query-optimization/chapter-01-execution-plan.html">查询执行流程与 EXPLAIN</a>。</li><li data-src-line="46" data-src-file="mysql/01-basics/chapter-01-overview.md">并发读写冲突、死锁排查：阅读<a href="./../05-transaction-lock/chapter-01-overview.html">事务与锁：综览</a>。</li><li data-src-line="47" data-src-file="mysql/01-basics/chapter-01-overview.md">遇到中文、emoji 或排序比较问题：阅读<a href="./../06-sql-and-schema/chapter-01-charset-collation.html">字符集与排序规则</a>。</li><li data-src-line="48" data-src-file="mysql/01-basics/chapter-01-overview.md">想从任务入口开始：返回<a href="./../">MySQL 专项首页</a>。</li></ul>',16)])])}const p=e(i,[["render",s]]);export{f as __pageData,p as default};
